import urllib.request,json
for url in ['https://mapsneu.wien.gv.at/basemapv/bmapvhl/3857/','https://mapsneu.wien.gv.at/basemapv/bmapvhl/3857/tile/{z}/{y}/{x}.pbf']:
 print('url',url)
 try:
  with urllib.request.urlopen(url, timeout=20) as r: data=r.read()
  print(r.status, r.getheader('content-type'), len(data), data[:300])
  if data[:1] in [b'{',b'[']:
   s=json.loads(data); print(json.dumps({k:s.get(k) for k in ['tilejson','name','scheme','tiles','bounds','minzoom','maxzoom','vector_layers']},ensure_ascii=False)[:3000])
 except Exception as e: print(type(e).__name__, e)
