import json
from pathlib import Path
CONTOUR_SOURCE='basemap-at-hoehenlinien'
CONTOUR_OPACITY=0.18
for p in [Path('config/map_styles/austrian_rocks_light.json'), Path('config/map_styles/austrian_rocks_dark.json')]:
    style=json.loads(p.read_text())
    for layer in style['layers']:
        if layer.get('source') == CONTOUR_SOURCE:
            paint=layer.setdefault('paint', {})
            if layer.get('type') == 'line':
                paint['line-opacity']=CONTOUR_OPACITY
            elif layer.get('type') == 'symbol':
                paint['text-opacity']=CONTOUR_OPACITY
    p.write_text(json.dumps(style, ensure_ascii=False, separators=(',', ':'))+'\n')
PY

